when.set-body:
@{
                    var raw = (string)context.Variables["backendBody"];
                    JToken detail;
                    try { detail = JToken.Parse(raw); } catch { detail = raw; }
                    var headers = context.Response.Headers;
                    return new JObject(
                        new JProperty("source", "foundry-backend"),
                        new JProperty("statusCode", context.Response.StatusCode),
                        new JProperty("reason", context.Response.StatusReason),
                        new JProperty("backendRequestId", headers.GetValueOrDefault("apim-request-id", headers.GetValueOrDefault("x-request-id", ""))),
                        new JProperty("wwwAuthenticate", headers.GetValueOrDefault("WWW-Authenticate", "")),
                        new JProperty("gatewayRequestId", context.RequestId.ToString()),
                        new JProperty("backendError", detail)
                    ).ToString();
                }

set-status.code:
@{
                var src = context.LastError.Source ?? "";
                var reason = context.LastError.Reason ?? "";
                if (reason == "SubscriptionKeyNotFound" || reason == "SubscriptionKeyInvalid") { return 401; }
                if (src.StartsWith("validate")) { return 401; }
                if (reason.Contains("Timeout")) { return 504; }
                if (src == "forward-request") { return 502; }
                return 500;
            }

return-response.set-body:
@{
                var e = context.LastError;
                return new JObject(
                    new JProperty("source", e.Source ?? ""),
                    new JProperty("reason", e.Reason ?? ""),
                    new JProperty("message", e.Message ?? ""),
                    new JProperty("section", e.Section ?? ""),
                    new JProperty("scope", e.Scope ?? ""),
                    new JProperty("path", e.Path ?? ""),
                    new JProperty("policyId", e.PolicyId ?? ""),
                    new JProperty("backendStatusCode", context.Response?.StatusCode),
                    new JProperty("gatewayRequestId", context.RequestId.ToString())
                ).ToString();
            }
